def _associate_chunks_to_workers(num_workers: int, worker_env: _WorkerEnv, chunks_replica: List[int], intervals_replica: List[Any]) -> Any:

    chunk_assignments = {}
    interval_assignments = {}

    for worker_index in range(num_workers):
        start_index = (worker_index * len(chunks_replica)) // num_workers
        end_index = ((worker_index + 1) * len(chunks_replica)) // num_workers

        assigned_chunks = chunks_replica[start_index:end_index]
        assigned_intervals = intervals_replica[start_index:end_index]

        chunk_assignments[worker_index] = assigned_chunks
        interval_assignments[worker_index] = assigned_intervals

    return chunk_assignments, interval_assignments
